// ── Corrected 3D scene builder (self-contained IIFE) ─────────
let renderer3=null,scene3=null,camera3=null; // global — trengst for tema-toggle
(function setup3D(){
  let animId3=null;
  let isWire=false;
  let orb=false,pan=false,lastM={x:0,y:0};
  let sph={theta:0.7,phi:1.05,radius:60};
  // Solsimulering / opningsanimasjon / klikk-info
  let _sunOn=false,_sunMonth=6,_sunHour=12;
  let _growT0=0;
  let _picked=null,_downPos=null;
  let tgt={x:0,y:0,z:0};
  // Standardlyset. Summen av det diffuse lyset må liggje godt under 1,
  // elles vert alle flater mette og modellen ser flat ut — sola skal
  // vere det som skil taket frå veggane og ein fasade frå den neste.
  const LYS3D={amb:0.45,hemi:0.55,sun:1.15,fill:0.35};
  const OV=document.getElementById('model3dOverlay');
  const CV=document.getElementById('canvas3d');
  // Konverter COLORS hex-string til THREE-format og bruk same fargelogikk som 2D/sidepanel
  const hexToInt=h=>parseInt(h.replace('#',''),16);
  // Finn 3D-farge for ei sone — same gruppe-logikk som i canvas-draw og sidepanel
  function getZoneColor3D(z,fi,zi){
    let ci;
    if(z.groupId){
      let _fst=null;
      floors.forEach((fl,fli)=>fl.zones.forEach((zz,zzi)=>{if(!_fst&&zz.groupId===z.groupId)_fst={fli,zi:zzi};}));
      ci=_fst?(floors.slice(0,_fst.fli).reduce((s,fl)=>s+fl.zones.length,0)+_fst.zi)%COLORS.length:(floors.slice(0,fi).reduce((s,fl)=>s+fl.zones.length,0)+zi)%COLORS.length;
    } else {
      ci=(floors.slice(0,fi).reduce((s,fl)=>s+fl.zones.length,0)+zi)%COLORS.length;
    }
    return hexToInt(COLORS[ci]);
  }

  document.getElementById('btn3d').onclick=()=>{
    const allZ=floors.flatMap(f=>f.zones);
    if(!allZ.length){hintText.textContent='Teikn soner først.';return;}
    OV.style.display='flex';
    _showPlan=true;
    document.getElementById('model3dPlan').style.background='rgba(255,255,255,.2)';
    try{build();_skannStil();}catch(e){console.error('3D build error:',e);}
    // Byggje-animasjon — modellen veks opp frå grunnen
    if(scene3){scene3.scale.y=0.001;_growT0=performance.now();}
    start();
    // Fyrste gong 3D vert opna etter ein skann-import, kjem skannet med
    // bileta fram av seg sjølv — knappen åleine vart ikkje funnen.
    if(mpSkann&&!mpSkann._autoVist&&!_showScan){mpSkann._autoVist=true;scanBtn3.onclick();}
  };
  document.getElementById('model3dClose').onclick=()=>{OV.style.display='none';stop();};
  document.getElementById('model3dReset').onclick=recenter;
  document.getElementById('model3dWire').onclick=()=>{
    isWire=!isWire;
    document.getElementById('model3dWire').style.background=isWire?'rgba(255,255,255,.2)':'transparent';
    if(!scene3)return;
    scene3.traverse(o=>{if(o.isMesh&&o.userData.w)o.material.wireframe=isWire;});
  };

  // Skannet (MatterPak) — lastast fyrst når nokon ber om det: teksturane
  // tek nokre sekund å dekode, og dei fleste opnar 3D for å sjå sonene.
  let _showScan=false;
  const scanBtn3=document.getElementById('model3dScan');
  scanBtn3.onclick=async()=>{
    if(!mpSkann)return;
    if(!_showScan&&!mpSkann.gruppe){
      scanBtn3.disabled=true;
      try{await mpByggSkann3D(t=>{scanBtn3.textContent=t;});}
      catch(e){alert('Kunne ikkje vise skannet: '+e.message);}
      scanBtn3.disabled=false;scanBtn3.textContent='📷 Skann';
      if(!mpSkann||!mpSkann.gruppe)return;
    }
    _showScan=!_showScan;
    scanBtn3.style.background=_showScan?'var(--accent)':'transparent';scanBtn3.style.color=_showScan?'#fff':'var(--dm-t2,#4b5563)';
    window._rebuild3D();
  };

  // Med skannet framme vert sonemodellen gjennomsiktig: taket på sonene
  // ville elles dekt skannet, og poenget er å samanlikne dei to.
  function _skannStil(){
    if(!scene3||!_showScan)return;
    scene3.traverse(o=>{
      if(!o.isMesh||!o.userData.w)return;
      const ms=Array.isArray(o.material)?o.material:[o.material];
      o.material=ms.map(m=>{const c=m.clone();c.transparent=true;c.opacity=0.18;c.depthWrite=false;return c;});
      if(o.material.length===1)o.material=o.material[0];
      o.castShadow=false;
    });
  }

  let _showPlan=true;
  document.getElementById('model3dPlan').onclick=()=>{
    _showPlan=!_showPlan;
    document.getElementById('model3dPlan').style.background=_showPlan?'rgba(255,255,255,.2)':'transparent';
    if(!scene3)return;
    scene3.traverse(o=>{
      if(o.userData._isGroundPlane)o.visible=_showPlan;
    });
  };

  // Den gamle scena må gi geometriar, materiale, teksturar og skuggekart
  // tilbake til grafikkortet. Utan dette lak kvar ombygging alt: på eit bygg
  // med 20 soner gjekk geometriane frå 615 til 3685 på fem ombyggingar, og
  // tida per ombygging dobla seg. Skannet (mpSkann.gruppe) vert gjenbrukt
  // mellom scenene og vert difor teke ut før ryddinga, aldri frigjort her.
  function _ryddScene(s){
    if(!s)return;
    const skann=(typeof mpSkann!=='undefined'&&mpSkann)?mpSkann.gruppe:null;
    if(skann&&skann.parent===s)s.remove(skann);
    const geo=new Set(),mat=new Set(),tex=new Set();
    s.traverse(o=>{
      if(o.geometry)geo.add(o.geometry);
      (Array.isArray(o.material)?o.material:(o.material?[o.material]:[])).forEach(m=>{
        mat.add(m);
        ['map','alphaMap','emissiveMap','normalMap'].forEach(k=>{if(m[k])tex.add(m[k]);});
      });
      if(o.isLight&&o.shadow&&o.shadow.map){o.shadow.map.dispose();o.shadow.map=null;}
    });
    geo.forEach(g=>g.dispose());tex.forEach(t=>t.dispose());mat.forEach(m=>m.dispose());
  }
  function build(){
    _clearPick(); // gamal scene vert kasta — fjern highlight/infoboks
    const W=CV.clientWidth||800,H=CV.clientHeight||500;
    if(!renderer3){
      // alpha: bakgrunnen (punktrutenett + logo) ligg i CSS på #model3dScene
      renderer3=new THREE.WebGLRenderer({canvas:CV,antialias:true,alpha:true});
      renderer3.setPixelRatio(Math.min(window.devicePixelRatio,2));
      renderer3.shadowMap.enabled=true;
      renderer3.shadowMap.type=THREE.PCFSoftShadowMap;
    }
    renderer3.setSize(W,H,false);
    const isDark3D=()=>document.documentElement.getAttribute('data-theme')==='dark';
    // Fargen er det tåka tonar mot — same som flata i #model3dScene
    const bg3Dlight=0xebeff3, bg3Ddark=0x0f1113;
    const getBg3D=()=>isDark3D()?bg3Ddark:bg3Dlight;
    renderer3.setClearColor(getBg3D(),0);

    _ryddScene(scene3);
    scene3=new THREE.Scene();
    scene3.fog=new THREE.Fog(getBg3D(),150,400);
    camera3=new THREE.PerspectiveCamera(42,W/H,0.1,800);

    // Lights — refs lagrast i userData slik at solsimuleringa kan styre dei.
    // Styrkane står i LYS3D, så solsimuleringa set same standard attende.
    const amb=new THREE.AmbientLight(0xffffff,LYS3D.amb);scene3.add(amb);
    const sun=new THREE.DirectionalLight(0xfff8f0,LYS3D.sun);
    sun.position.set(50,90,40);sun.castShadow=true;
    sun.shadow.mapSize.set(2048,2048);
    sun.shadow.bias=-0.0005;sun.shadow.normalBias=0.02;
    sun.shadow.camera.left=-100;sun.shadow.camera.right=100;sun.shadow.camera.top=100;sun.shadow.camera.bottom=-100;
    scene3.add(sun);
    const fill=new THREE.DirectionalLight(0xe8f4f2,LYS3D.fill);fill.position.set(-40,30,-30);scene3.add(fill);
    const hemi=new THREE.HemisphereLight(0xf8fafc,0x9ca3af,LYS3D.hemi);scene3.add(hemi);
    scene3.userData.amb=amb;scene3.userData.sun=sun;scene3.userData.fill=fill;scene3.userData.hemi=hemi;

    // Har bygget kjeller? Då vert heile stabelen senka slik at terrenget
    // ligg i y=0, og alt under planteikninga må kunne sjåast gjennom henne.
    const kjSink=kjellerSenking();
    const harKjeller3D=kjSink>0.001;

    // Skuggefangar — usynleg plan som tek imot skuggar oppå planteikninga.
    // Med kjeller ville han lagt eit grått slør over alt som ligg under.
    if(!harKjeller3D){
      const shadowCatcher=new THREE.Mesh(new THREE.PlaneGeometry(500,500),new THREE.ShadowMaterial({opacity:0.22}));
      shadowCatcher.rotation.x=-Math.PI/2;shadowCatcher.position.y=0.002;shadowCatcher.receiveShadow=true;
      scene3.add(shadowCatcher);
    }

    // Ground — planteikning på nedste etasje som bakkeplan
    (()=>{
      const groundFloor=floors[0];
      const gImg=groundFloor?.bgImg;
      const _gm=mppForFloor(groundFloor);
      if(gImg&&_gm){
        // Kalkuler storleik i meter
        const gW=gImg.width*_gm/1000;
        const gH=gImg.height*_gm/1000;
        // Offset for denne etasjen
        const fdxM=(groundFloor.floorDxImg||0)*_gm/1000;
        const fdyM=(groundFloor.floorDyImg||0)*_gm/1000;
        // Lag CanvasTexture frå bgImg
        const tc=document.createElement('canvas');
        tc.width=gImg.width;tc.height=gImg.height;
        tc.getContext('2d').drawImage(gImg,0,0);
        const tex=new THREE.CanvasTexture(tc);
        tex.flipY=true;
        // PlaneGeometry — XZ-plan (Y=0), midtpunkt justert mot cx/cz
        // cx/cz er bereknast seinare, men vi treng å plassere planet rett
        // Vi brukar center av biletet: offsetX=gW/2 - cx, offsetZ=gH/2 - cz
        // Sidan cx/cz ikkje er definert enno, lagrar vi geometrien og set posisjon etter cx/cz er kjend
        const geo=new THREE.PlaneGeometry(gW,gH);
        // MeshBasicMaterial: ikkje lysavhengig — teikninga vises fullt og klart.
        // Med kjeller under må ho vere delvis gjennomsiktig, og ho må teiknast
        // frå begge sider — ein ser henne nedanfrå når kameraet går under terreng.
        const mat=harKjeller3D
          ?new THREE.MeshBasicMaterial({map:tex,transparent:true,opacity:0.42,depthWrite:false,side:THREE.DoubleSide})
          :new THREE.MeshBasicMaterial({map:tex});
        const plane=new THREE.Mesh(geo,mat);
        if(harKjeller3D)plane.renderOrder=2;
        plane.rotation.x=-Math.PI/2;
        plane.userData._isGroundPlane=true;
        plane.userData._gW=gW;plane.userData._gH=gH;
        plane.userData._fdxM=fdxM;plane.userData._fdyM=fdyM;
        plane.position.y=-0.01;
        scene3.add(plane);
      }
      // Ingen anna underlag: den grå plata rundt teikninga og rutenettet (utan
      // teikning) er fjerna. Bakgrunnen er punktrutenettet i CSS, og skuggane
      // fell framleis på den usynlege skuggefangaren.
    })();

    // World centre
    let allPts=[];
    floors.forEach(f=>{
      const _fm=mppForFloor(f);
      if(_fm)f.zones.forEach(z=>{if(z.skjult)return;z.pts.forEach(p=>allPts.push({x:p.x*_fm/1000,z:p.y*_fm/1000}));});
    });
    let mnX=Infinity,mxX=-Infinity,mnZ=Infinity,mxZ=-Infinity;
    allPts.forEach(p=>{mnX=Math.min(mnX,p.x);mxX=Math.max(mxX,p.x);mnZ=Math.min(mnZ,p.z);mxZ=Math.max(mxZ,p.z);});
    if(!isFinite(mnX)){mnX=0;mxX=20;mnZ=0;mxZ=20;}
    const cx=(mnX+mxX)/2,cz=(mnZ+mxZ)/2;

    // Juster ground plane-posisjonen no som cx/cz er kjend
    scene3.traverse(o=>{
      if(o.userData._isGroundPlane){
        const gf=floors[0];
        const mpp=mmPerImgPx||10;
        // Bildets venstre kant i verdskoordinatar (utan offset): x = 0*mpp/1000 - cx
        // Sentrum av biletet: x = (gImg.width/2)*mpp/1000 - cx + fdxM
        const fdxM=o.userData._fdxM||0,fdyM=o.userData._fdyM||0;
        const gW=o.userData._gW,gH=o.userData._gH;
        o.position.x=(gW/2)-cx+fdxM;
        o.position.z=(gH/2)-cz+fdyM;
      }
    });

    // ── Sprite-helper: create a canvas texture label ──────────
    function makeLabel(text, opts={}){
      const fs=opts.fontSize||18;
      const fc=opts.color||'#1e293b';
      const bg=opts.bg||'rgba(255,255,255,0.92)';
      const pad=opts.pad||8;
      const bold=opts.bold?'bold ':'';
      const tc=document.createElement('canvas');
      const tx=tc.getContext('2d');
      tx.font=`${bold}${fs}px Inter,sans-serif`;
      const tw=tx.measureText(text).width;
      tc.width=Math.ceil(tw+pad*2);tc.height=Math.ceil(fs+pad*2);
      tx.font=`${bold}${fs}px Inter,sans-serif`;
      // Background pill
      tx.fillStyle=bg;
      tx.beginPath();
      const r=Math.min(8,tc.height/2);
      tx.moveTo(r,0);tx.lineTo(tc.width-r,0);
      tx.quadraticCurveTo(tc.width,0,tc.width,r);
      tx.lineTo(tc.width,tc.height-r);tx.quadraticCurveTo(tc.width,tc.height,tc.width-r,tc.height);
      tx.lineTo(r,tc.height);tx.quadraticCurveTo(0,tc.height,0,tc.height-r);
      tx.lineTo(0,r);tx.quadraticCurveTo(0,0,r,0);tx.closePath();tx.fill();
      // Border
      tx.strokeStyle=opts.border||'rgba(0,0,0,0.08)';tx.lineWidth=1;tx.stroke();
      tx.fillStyle=fc;tx.textBaseline='middle';tx.textAlign='left';
      tx.fillText(text,pad,tc.height/2);
      const tex=new THREE.CanvasTexture(tc);
      const mat=new THREE.SpriteMaterial({map:tex,transparent:true,depthTest:false});
      const sp=new THREE.Sprite(mat);
      // Scale so label is roughly constant screen size; base unit ~0.5m per 18px-font
      const scale=opts.scale||(tc.width/tc.height*0.6);
      sp.scale.set(scale,0.6,1);
      return sp;
    }

    // Sonekort: fleire liner i éin lapp (namn, areal/volum, tak). Høgda i
    // verda følgjer talet på liner, og breidda sideforholdet — dei gamle
    // einskildlappane vart strekte til ei fast breidd.
    function makeKort(liner,kant){
      const pad=9,gap=4,tc=document.createElement('canvas'),tx=tc.getContext('2d');
      const font=l=>`${l.bold?'bold ':''}${l.fs}px Inter,sans-serif`;
      let W=0,Hh=pad*2-gap;
      liner.forEach(l=>{tx.font=font(l);W=Math.max(W,tx.measureText(l.t).width);Hh+=l.fs+gap;});
      const S=2;   // dobbel oppløysing — skarpare tekst
      tc.width=Math.ceil((W+pad*2)*S);tc.height=Math.ceil(Hh*S);
      tx.scale(S,S);
      const w=tc.width/S,hh=tc.height/S,r=8;
      tx.fillStyle='rgba(255,255,255,0.94)';
      tx.beginPath();tx.moveTo(r,0);tx.lineTo(w-r,0);tx.quadraticCurveTo(w,0,w,r);tx.lineTo(w,hh-r);
      tx.quadraticCurveTo(w,hh,w-r,hh);tx.lineTo(r,hh);tx.quadraticCurveTo(0,hh,0,hh-r);tx.lineTo(0,r);
      tx.quadraticCurveTo(0,0,r,0);tx.closePath();tx.fill();
      tx.strokeStyle=kant||'rgba(0,0,0,0.1)';tx.lineWidth=1.5;tx.stroke();
      let y=pad;
      tx.textAlign='center';tx.textBaseline='top';
      liner.forEach(l=>{tx.font=font(l);tx.fillStyle=l.c||'#374151';tx.fillText(l.t,w/2,y);y+=l.fs+gap;});
      const tex=new THREE.CanvasTexture(tc);tex.minFilter=THREE.LinearFilter;
      const sp=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true,depthTest:false}));
      const hM=0.023*hh;
      sp.scale.set(hM*w/hh,hM,1);
      sp.renderOrder=10;
      return sp;
    }

    // ── Dimension line helper ──────────────────────────────────
    function addDimLine(p1,p2,label,yOff,color){
      color=color||0x64748b;
      const pts3=[new THREE.Vector3(p1.x,yOff,p1.z),new THREE.Vector3(p2.x,yOff,p2.z)];
      const geo=new THREE.BufferGeometry().setFromPoints(pts3);
      scene3.add(new THREE.Line(geo,new THREE.LineBasicMaterial({color,linewidth:1,transparent:true,opacity:0.6})));
      // Tick marks at ends
      const dx=p2.x-p1.x,dz=p2.z-p1.z;
      const len=Math.hypot(dx,dz)||1;
      const nx=-dz/len*0.3,nz=dx/len*0.3;
      [p1,p2].forEach(p=>{
        const tGeo=new THREE.BufferGeometry().setFromPoints([
          new THREE.Vector3(p.x+nx,yOff,p.z+nz),new THREE.Vector3(p.x-nx,yOff,p.z-nz)
        ]);
        scene3.add(new THREE.Line(tGeo,new THREE.LineBasicMaterial({color,transparent:true,opacity:0.5})));
      });
      // Label sprite at midpoint
      const sp=makeLabel(label,{fontSize:14,color:'#475569',bg:'rgba(241,245,249,0.93)',border:'rgba(100,116,139,0.2)',scale:undefined});
      sp.position.set((p1.x+p2.x)/2,(yOff)+0.35,(p1.z+p2.z)/2);
      sp.userData.prio=1+Math.min(0.9,len/100);   // lengre vegg vinn
      scene3.add(sp);
    }

    // ── Height dimension helper ────────────────────────────────
    function addHeightDim(x,y0,y1,z,label,color){
      color=color||0x0e6b5e;
      const pts3=[new THREE.Vector3(x,y0,z),new THREE.Vector3(x,y1,z)];
      const geo=new THREE.BufferGeometry().setFromPoints(pts3);
      scene3.add(new THREE.Line(geo,new THREE.LineBasicMaterial({color,linewidth:2,transparent:true,opacity:0.7})));
      // Tick marks
      const off=0.25;
      [[x-off,y0,z],[x+off,y0,z],[x-off,y1,z],[x+off,y1,z]].reduce((a,b,i)=>{
        if(i%2===1){const g=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(...a),new THREE.Vector3(...b)]);scene3.add(new THREE.Line(g,new THREE.LineBasicMaterial({color,transparent:true,opacity:0.6})));}
        return b;
      });
      const sp=makeLabel(label,{fontSize:13,color:'#1d4f4f',bg:'rgba(240,253,250,0.95)',border:'rgba(29,79,79,0.2)',bold:true});
      sp.position.set(x+0.5,(y0+y1)/2,z);
      sp.userData.prio=2;
      scene3.add(sp);
    }

    // Stack floors — bruk etasjens defaultHoyde som stakkingshøgde.
    // Med kjeller startar stabelen under null, slik at oppfyllingskanten til
    // den nedste kjelleretasjen fell saman med terrenget (planteikninga, y=0).
    // Delplanar står på same nivå som hovudetasjen sin (etasjeGrunnhoyder).
    const floorBaseY=etasjeGrunnhoyder().map(b=>b-kjSink);

    // Skannet i same verd som sonene: (X−ox) m er biletpikslar × MP_PX, så
    // ein faktor k tek omkalibrering med. Golvet i fyrste etasje i skannet
    // (z0) ligg på grunnhøgda til fyrste etasje. Planteikninga under vert
    // gøymd — ho ligg i same plan som skann-golvet og ville flimra.
    scanBtn3.style.display=mpSkann?'':'none';
    if(!mpSkann)_showScan=false;
    if(_showScan&&mpSkann&&mpSkann.gruppe&&floors[0]){
      const f0=floors[0],m0=mppForFloor(f0)||MP_PX*1000,k=m0/(MP_PX*1000);
      const g=mpSkann.gruppe;
      g.scale.set(k,1,k);
      g.position.set(-cx+(f0.floorDxImg||0)*m0/1000,(floorBaseY[0]||0)-mpSkann.z0,-cz+(f0.floorDyImg||0)*m0/1000);
      scene3.add(g);
      scene3.traverse(o=>{if(o.userData._isGroundPlane)o.visible=false;});
    }

    const legendEl=document.getElementById('model3dLegend');
    legendEl.innerHTML='';
    const seenNames=new Set();

    // Delte material for vindauge og dører
    const WIN3D={
      // Halvgjennomsiktig glas — ein ser inn i bygget, som gjennom eit vindauge.
      // depthWrite av, elles skjuler glaset det som ligg bak i rekkjefølgja.
      glas:new THREE.MeshLambertMaterial({color:0x8ec5e8,side:THREE.DoubleSide,transparent:true,opacity:0.32,depthWrite:false}),
      dor:new THREE.MeshLambertMaterial({color:0x334155,side:THREE.DoubleSide}),
      // Tynn, dempa kant — markerer opninga mot veggen utan å bli ein karm
      kant:new THREE.LineBasicMaterial({color:0x1e293b,transparent:true,opacity:0.7})
    };
    // Alle glas og dørblad er rektangel: éin delt 1×1 m-geometri med kant,
    // skalert til storleiken. Før fekk kvar rute eigen PlaneGeometry og eigen
    // EdgesGeometry — 408 kantar på eit bygg med 102 opningar, ein tredel av
    // byggjetida for modellen.
    WIN3D.rute=new THREE.PlaneGeometry(1,1);
    WIN3D.ruteKant=new THREE.EdgesGeometry(WIN3D.rute);

    floors.forEach((f,fi)=>{
      const baseY=floorBaseY[fi];
      f.zones.forEach((z,zi)=>{
        if(z.pts.length<3||z.skjult)return;
        const col=getZoneColor3D(z,fi,zi);
        const colHex='#'+col.toString(16).padStart(6,'0');
        const fh=getHoyde(z);
        const him=getHimling(z);

        // Legg til etasje-offset — floorDxImg er i biletpikslar, direkte til meter
        const _fm=mppForFloor(f);
        const fdxM=(f.floorDxImg||0)*(_fm||10)/1000;
        const fdyM=(f.floorDyImg||0)*(_fm||10)/1000;
        const toM=p=>({x:(_fm?p.x*_fm/1000:p.x/10)-cx+fdxM,z:(_fm?p.y*_fm/1000:p.y/10)-cz+fdyM});
        const ptsM=z.pts.map(toM);
        // Kantfarge: ein mørkare tone av sonefargen — i same farge som
        // veggen vart kantane borte, og forma med dei
        const edgeMat=new THREE.LineBasicMaterial({color:new THREE.Color(col).multiplyScalar(0.55),transparent:true,opacity:0.8});

        // (Ingen golv-slab — unngår skugge-artefakt)

        // Walls per segment
        const sk=z.skillevegg||new Set();
        const segs=calcSegments(z.pts,fh,_fm)||[];
        const wins=z.windows||[];
        // Omløpet i (x,z): positivt areal ⇒ venstrenormalen peikar inn i sona
        let _a2=0;ptsM.forEach((p,i)=>{const q=ptsM[(i+1)%ptsM.length];_a2+=p.x*q.z-q.x*p.z;});
        const oSign=_a2>0?-1:1;
        const _sDir=i=>{const a=toM(segs[i].p1),b=toM(segs[i].p2),L=Math.hypot(b.x-a.x,b.z-a.z)||1;return{x:(b.x-a.x)/L,z:(b.z-a.z)/L};};
        // Kor langt veggen må forlengjast i kvar ende for at dei ytre flatene
        // skal møtast i hjørnet (0 i eit innvendig hjørne, maks 3 × tjukna)
        // Skiljekonstruksjonar og sonekoplingar er innvendige: dei har inga
        // tjukn i modellen (ei flate på sonekanten), og ein yttervegg som møter
        // ein slik vegg sluttar i hjørnet — elles stikk han inn i ytterveggen
        // til nabosona og ligg dobbelt oppå han.
        const _zc=z.zoneConnections;
        const _innv=i=>sk.has(i)||!!(_zc&&typeof _zc.has==='function'&&_zc.has(i));
        const _veggEnde=(i,isSK,t)=>{
          if(isSK)return{s:0,e:0};
          const n=segs.length,d=_sDir(i),o={x:-d.z*oSign,z:d.x*oSign};
          const cr=(ax,az,bx,bz)=>ax*bz-az*bx;
          const ende=(j,fram)=>{
            if(_innv(segs[j].idx))return 0;
            const dj=_sDir(j),oj={x:-dj.z*oSign,z:dj.x*oSign};
            const den=cr(d.x,d.z,dj.x,dj.z);if(Math.abs(den)<1e-6)return 0;
            const s=cr((oj.x-o.x)*t,(oj.z-o.z)*t,dj.x,dj.z)/den;
            return Math.max(0,Math.min(3*t,fram?s:-s));
          };
          return{s:ende((i-1+n)%n,false),e:ende((i+1)%n,true)};
        };

        segs.forEach((seg)=>{
          const isSK=_innv(seg.idx);
          const p1=toM(seg.p1),p2=toM(seg.p2);
          const dx=p2.x-p1.x,dz=p2.z-p1.z;
          const segLen=Math.hypot(dx,dz);
          if(segLen<0.02)return;
          const ang=Math.atan2(dz,dx);
          const thick=isSK?0:0.25;
          const wallCol=isSK?0x475569:col;
          const wallOp=isSK?0.6:1.0;

          const segWins=wins.filter(w=>w.segIdx===seg.idx);
          const wallMat=new THREE.MeshLambertMaterial({color:wallCol,transparent:wallOp<1,opacity:wallOp,
            side:isSK?THREE.DoubleSide:THREE.FrontSide,depthWrite:!isSK});
          wallMat.userData={baseColor:wallCol};
          // Veggen står UTANFOR sonekanten — sonekanten er innsida av
          // ytterveggen, slik sonene vert teikna. Skiljeveggar står midt på.
          // Endane vert forlengde til hjørnet der dei ytre flatene møtest, så
          // hjørna er lukka. Berre visning — lengda som vert vist og
          // eksportert er seg.lenM.
          const nx_=-dz/segLen,nz_=dx/segLen;
          const ox=nx_*oSign,oz=nz_*oSign;              // utvendig normal
          const zOff=isSK?0:(oSign>0?0:-thick);  // lokal z (= n_) der veggen byrjar
          const ext=_veggEnde(seg.idx,isSK,thick);
          // Opningane som hòl i veggen (u langs veggen frå p1, v opp frå golvet)
          const opn=[];
          segWins.forEach(w=>{
            expandWindows(w,segLen).forEach(ew=>{
              const isDoor=ew.type==='dor';
              const openH=ew.hoyMm/1000;
              // Brystning: manuell (brystningMm) → midtstilt → 0 for dør
              const sillH=isDoor?0:(ew.brystningMm!=null?ew.brystningMm/1000:Math.max(0,(fh-openH)/2));
              const openW=ew.breddeMm/1000; // alltid frå breddeMm, ikkje t1-t0
              if(!(openW>0.05&&openH>0.05))return;
              opn.push({w,ew,isDoor,sillH,openH,openW,uc:segLen*(ew.t0+ew.t1)/2});
            });
          });
          const wallGeo=_veggGeo(segLen,fh,thick,ext.s,ext.e,opn.map(o=>({
            u0:o.uc-o.openW/2,u1:o.uc+o.openW/2,v0:o.sillH,v1:o.sillH+o.openH})));
          const wall=new THREE.Mesh(wallGeo,wallMat);
          wall.position.set(p1.x+nx_*zOff,baseY,p1.z+nz_*zOff);
          wall.rotation.y=-ang;wall.castShadow=!isSK;wall.receiveShadow=true;
          wall.userData.w=true;
          if(!isSK)wall.add(new THREE.LineSegments(new THREE.EdgesGeometry(wallGeo),edgeMat));
          // Klikk-info for denne veggen — her bur no lengda og areala som
          // før stod som lappar på modellen
          const opnA=segWins.reduce((s,w)=>s+winCount(w)*(w.breddeMm||0)*(w.hoyMm||0)/1e6,0);
          wall.userData.pick={
            title:z.name+' — '+(sk.has(seg.idx)?'skiljevegg':isSK?'sonekopling':'fasade '+seg.dir),
            rows:[
              ['Etasje',f.name],
              ['Lengd',seg.lenM!=null?seg.lenM.toFixed(2)+' m':'ikkje kalibrert'],
              ['Høgd',fh.toFixed(2)+' m'],
              ['Bruttoareal',seg.areaM2!=null?seg.areaM2.toFixed(2)+' m²':'—'],
              ['Vindauge/dører',String(segWins.reduce((s,w)=>s+(w.antal||1),0))
                +(opnA>0?' · '+opnA.toFixed(2)+' m²':'')],
              ...(seg.areaM2!=null&&opnA>0?[['Nettoareal',Math.max(0,seg.areaM2-opnA).toFixed(2)+' m²']]:[]),
              ['U-vegg',(z.uVegg??entroStandard(z.byggeaar)?.uVegg)!=null?((z.uVegg??entroStandard(z.byggeaar).uVegg).toFixed(2)+' W/m²K'+(z.uVegg!=null?' (manuell)':'')):'—']
            ]
          };
          scene3.add(wall);

          // Glas og dørblad i opninga, inne i veggen (lysninga syner rundt).
          // Med vilje utan handtak og vassbrett — modellen skal vise kvar
          // opningane er og kor store dei er, ikkje teikne bygget.
          const glasZ=isSK?0:zOff+thick*0.4;
          opn.forEach(o=>{
            const {w,ew,isDoor,sillH,openH,openW}=o;
            const ocx=p1.x+dx/segLen*o.uc+nx_*glasZ,ocz=p1.z+dz/segLen*o.uc+nz_*glasZ;
            const ocy=baseY+sillH+openH/2;
            const pickInfo={
              title:z.name+' — '+(ew.name||w.name||(isDoor?'Dør':'Vindauge')),
              rows:[
                ['Type',isDoor?'Dør':'Vindauge'],
                ['Storleik',Math.round(ew.breddeMm)+' × '+Math.round(ew.hoyMm)+' mm'],
                ...(isDoor?[]:[['Brystning',Math.round(sillH*1000)+' mm']]),
                ['Antal i gruppa',String(winCount(w))],
                ['Fasade',seg.dir||'—']
              ]
            };
            // Klona per flate: klikk-markeringa set emissive på materialet
            const m=new THREE.Mesh(WIN3D.rute,(isDoor?WIN3D.dor:WIN3D.glas).clone());
            m.position.set(ocx,ocy,ocz);m.rotation.y=-ang;m.scale.set(openW,openH,1);
            m.userData.pick=pickInfo;
            // Karmen: ein tynn ramme rundt glaset/dørbladet (skalert med flata)
            const kant=new THREE.LineSegments(WIN3D.ruteKant,WIN3D.kant);
            m.add(kant);
            scene3.add(m);
          });

          // Vegglengd og areal står ikkje som lappar lenger (det vart uleseleg
          // på store bygg) — dei kjem fram ved klikk på veggen (userData.pick).
        });

        // Golv- og takkant
        [baseY,baseY+fh].forEach(ey=>{
          const edPts=ptsM.map(p=>new THREE.Vector3(p.x,ey,p.z));
          edPts.push(edPts[0].clone());
          scene3.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(edPts),edgeMat));
        });

        // Tak — skrå takflater om definert, elles flatt
        const TF3D_PAL=[0xfbbf24,0x6366f1,0xec4899,0x22c55e,0xf97316,0x14b8a6];
        if((z.takflater||[]).length>0){
          z.takflater.forEach((tf,tfi)=>{
            if((tf.pts||[]).length<3)return;
            const tfPtsM=tf.pts.map(toM);
            const tfShape=new THREE.Shape(tfPtsM.map(p=>new THREE.Vector2(p.x,p.z)));
            const tfGeo2d=new THREE.ShapeGeometry(tfShape);
            const tfPos=tfGeo2d.attributes.position;
            const n=tfPos.count;
            // retning = nedretning (dit vatn renn). Oppoverbakke = retning+180°.
            // 3D-aksane følgjer BILETET (x=bilet-x, z=bilet-y), ikkje kompasset —
            // legg til nord-rotasjonen slik at kompass-retninga vert bilderetning
            const _retRad=((tf.retning||0)+(parseFloat(northI.value)||0))*Math.PI/180;
            const ux=-Math.sin(_retRad),uz=Math.cos(_retRad);
            // Ei himling mot ei anna sone er flat — ho har inga fallretning
            const _tfTyp=flateType(z,'tak',tf);
            const _erTak=_tfTyp==='Tak';
            const tanV=_erTak?Math.tan(Math.max(0,(tf.vinkel||0))*Math.PI/180):0;
            let minProj=Infinity;
            for(let i=0;i<n;i++){const proj=tfPos.getX(i)*ux+tfPos.getY(i)*uz;if(proj<minProj)minProj=proj;}
            const verts=new Float32Array(n*3);
            for(let i=0;i<n;i++){
              const px=tfPos.getX(i),py=tfPos.getY(i);
              const h=Math.max(0,(px*ux+py*uz-minProj))*tanV;
              verts[i*3]=px;verts[i*3+1]=baseY+fh+h;verts[i*3+2]=py;
            }
            const tfNewGeo=new THREE.BufferGeometry();
            tfNewGeo.setAttribute('position',new THREE.BufferAttribute(verts,3));
            if(tfGeo2d.index)tfNewGeo.setIndex(tfGeo2d.index);
            tfNewGeo.computeVertexNormals();
            // Himlingar får ein dempa gråtone, så ein ser med ein gong kva
            // som er tak mot det fri og kva som grensar mot ei anna sone
            const tfColor=_erTak?TF3D_PAL[tfi%TF3D_PAL.length]:0x94a3b8;
            // Ei himling er ein skiljekonstruksjon — godt gjennomsiktig, så ein
            // ser ned i sona under (som skiljeveggane, som er flate og dempa)
            const tfMat=new THREE.MeshLambertMaterial({color:tfColor,side:THREE.DoubleSide,transparent:true,
              opacity:_erTak?0.82:0.22,depthWrite:_erTak});
            const tfMesh=new THREE.Mesh(tfNewGeo,tfMat);
            tfMesh.userData.w=true;
            const _uTf=tf.uverdi??z.uTak??entroStandard(z.byggeaar)?.uTak;
            tfMesh.userData.pick={
              title:z.name+' — '+(tf.name||('Takflate '+(tfi+1))),
              rows:[
                ['Etasje',f.name],
                ['Type',_tfTyp],
                ...(_erTak?[['Takvinkel',(tf.vinkel||0)+'°'],['Fallretning',(tf.retning??180)+'°']]:[]),
                ['Areal',flateAreaM2(z,tf).toFixed(2)+' m²'],
                ['U-verdi',_uTf!=null?(_uTf.toFixed(2)+' W/m²K'+(tf.uverdi!=null?' (eiga)':'')):'—']
              ]
            };
            scene3.add(tfMesh);
            // Kontur — hoppar over nøkkelhòl-brua, som ikkje er ein ekte kant
            const kon3=flateKonturar(tf.pts);
            kon3.deler.forEach(del=>{
              const dp=del.map(toM).map(p=>{const proj=p.x*ux+p.z*uz;return new THREE.Vector3(p.x,baseY+fh+Math.max(0,(proj-minProj))*tanV,p.z);});
              if(kon3.lukka&&dp.length)dp.push(dp[0].clone());
              if(dp.length>1)scene3.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(dp),new THREE.LineBasicMaterial({color:tfColor,linewidth:1})));
            });
          });
        } else {
          // Flatt tak. Himling mot ei anna sone er skiljekonstruksjon: gjennomsiktig
          const _erHim=(z.taktype||'Tak')!=='Tak';
          const ceilMat=new THREE.MeshLambertMaterial({color:_erHim?0x94a3b8:col,side:THREE.DoubleSide,
            transparent:_erHim,opacity:_erHim?0.22:1,depthWrite:!_erHim});
          const ceilShape=new THREE.Shape(ptsM.map(p=>new THREE.Vector2(p.x,p.z)));
          const ceilGeo=new THREE.ShapeGeometry(ceilShape);
          const ceil=new THREE.Mesh(ceilGeo,ceilMat);
          ceil.rotation.x=Math.PI/2;
          ceil.position.y=baseY+fh;
          ceil.receiveShadow=true;ceil.userData.w=true;scene3.add(ceil);
          const ceilEdgePts=ptsM.map(p=>new THREE.Vector3(p.x,baseY+fh,p.z));
          ceilEdgePts.push(ceilEdgePts[0].clone());
          scene3.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(ceilEdgePts),edgeMat));
        }

        // ── Gavlflater — trekantforma veggar over veggtopp ──
        (z.gavlflater||[]).forEach(gavl=>{
          const gseg=segs.find(s=>s.idx===gavl.segIdx);
          if(!gseg||!gavl.profile||gavl.profile.length<2)return;
          const gp1=toM(gseg.p1),gp2=toM(gseg.p2);
          const n=gavl.profile.length;
          // Bygger verteks-array: øvre profil + nedre kant (spegla)
          const vArr=[];
          gavl.profile.forEach(({t,h})=>{
            vArr.push(gp1.x+(gp2.x-gp1.x)*t,baseY+fh+h,gp1.z+(gp2.z-gp1.z)*t);
          });
          for(let i=n-1;i>=0;i--){
            const t=gavl.profile[i].t;
            vArr.push(gp1.x+(gp2.x-gp1.x)*t,baseY+fh,gp1.z+(gp2.z-gp1.z)*t);
          }
          // Fan-triangulering frå vertex 0 (begge sider)
          const totalV=vArr.length/3;
          const idxArr=[];
          for(let i=1;i<totalV-1;i++){idxArr.push(0,i,i+1);idxArr.push(0,i+1,i);}
          const geo=new THREE.BufferGeometry();
          geo.setAttribute('position',new THREE.BufferAttribute(new Float32Array(vArr),3));
          geo.setIndex(idxArr);
          geo.computeVertexNormals();
          const gavlMat=new THREE.MeshLambertMaterial({color:col,side:THREE.DoubleSide});
          gavlMat.userData={baseColor:col};
          const mesh=new THREE.Mesh(geo,gavlMat);
          mesh.castShadow=true;mesh.userData.w=true;
          scene3.add(mesh);
          // Kontur-linje
          const contourPts=[
            ...gavl.profile.map(({t,h})=>new THREE.Vector3(gp1.x+(gp2.x-gp1.x)*t,baseY+fh+h,gp1.z+(gp2.z-gp1.z)*t)),
            new THREE.Vector3(gp2.x,baseY+fh,gp2.z),
            new THREE.Vector3(gp1.x,baseY+fh,gp1.z),
            new THREE.Vector3(gp1.x+(gp2.x-gp1.x)*gavl.profile[0].t,baseY+fh+gavl.profile[0].h,gp1.z+(gp2.z-gp1.z)*gavl.profile[0].t)
          ];
          scene3.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(contourPts),edgeMat));
        });

        // ── Areal-label på golvet ──
        const area=getAreaM2(z);
        if(area){
          const cxM=ptsM.reduce((s,p)=>s+p.x,0)/ptsM.length;
          const czM=ptsM.reduce((s,p)=>s+p.z,0)/ptsM.length;
          const takvinkel=getTakvinkel(z);

          // Eitt kort per sone: namn, areal og volum, og taket når det
          // skil seg frå golvarealet (skrått tak) — likt areal står ikkje to gonger.
          const takA=getTakAreal(z),vol=getVolum(z);
          // Høgda står her i staden for som eigne høgdemål på veggen
          const liner=[{t:z.name,fs:15,bold:true,c:colHex},
            {t:area.toFixed(1)+' m²'+(vol?' · '+vol.toFixed(0)+' m³':'')+' · h '+fh.toFixed(1)+' m'
              +(Math.abs(him-fh)>0.005?' (himling '+him.toFixed(1)+')':''),fs:12}];
          if(takA&&(z.taktype||'Tak')==='Tak'&&(takvinkel>0||Math.abs(takA-area)>0.05))
            liner.push({t:'Tak '+takA.toFixed(1)+' m²'+(takvinkel>0?' ∠'+takvinkel+'°':''),fs:11,c:'#4338ca'});
          const kort=makeKort(liner,colHex+'88');
          kort.position.set(cxM,baseY+fh+0.6,czM);
          kort.userData.prio=3+Math.min(0.9,area/10000);   // større sone vinn
          scene3.add(kort);
        }

        // Legend
        if(!seenNames.has(z.name)){
          seenNames.add(z.name);
          const le=document.createElement('div');
          le.style.cssText=`display:flex;align-items:center;gap:5px;padding:3px 9px;background:var(--dm-glass,rgba(255,255,255,.9));border:1px solid var(--dm-bd,#e5e7eb);border-radius:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)`;
          const area=getAreaM2(z);
          le.innerHTML=`<span style="width:8px;height:8px;border-radius:2px;background:${colHex};flex-shrink:0"></span><span style="font-size:11px;color:var(--dm-t2,#374151);font-weight:500">${z.name}${area?' · '+area.toFixed(0)+' m²':''}</span>`;
          legendEl.appendChild(le);
        }
      });
    });

    // ── Morten for scale ──────────────────────────────────────
    let mortenSprite=null;
    (()=>{
      const MORTEN_H=1.80;
      const img=new Image();
      img.onload=()=>{
        const aspect=img.naturalWidth/img.naturalHeight;
        const tc=document.createElement('canvas');
        tc.height=512;tc.width=Math.round(512*aspect);
        const tx=tc.getContext('2d');
        tx.drawImage(img,0,0,tc.width,tc.height);

        const tex=new THREE.CanvasTexture(tc);
        // Loddrett flate med føtene i y=0 (terrenget — med kjeller er stabelen
        // senka, så bakkeplanet er framleis y=0). Ein Sprite vender heilt mot
        // kameraet og vippar difor nedre halvdel under bakken når ein ser
        // skrått ovanfrå; der vart han dekt av planteikninga. Flata dreiar
        // berre rundt si eiga loddlinje, og vert teikna etter teikninga.
        const geo=new THREE.PlaneGeometry(MORTEN_H*aspect,MORTEN_H);
        geo.translate(0,MORTEN_H/2,0);
        const mat=new THREE.MeshBasicMaterial({map:tex,transparent:true,alphaTest:0.1,side:THREE.DoubleSide});
        mortenSprite=new THREE.Mesh(geo,mat);
        mortenSprite.position.set(mxX-cx+1.4,0,mxZ-cz+0.9);
        mortenSprite.renderOrder=3;
        mortenSprite.onBeforeRender=(r,s,cam)=>{
          mortenSprite.rotation.y=Math.atan2(cam.position.x-mortenSprite.position.x,cam.position.z-mortenSprite.position.z);
          mortenSprite.updateMatrixWorld(true);
        };
        scene3.add(mortenSprite);
      };
      img.src='data:image/png;base64,';
    })();
    // (Nordpil fjerna — nord vert vist i kompassen på 2D-canvaset)

    // Info bar
    const totalA=floors.flatMap(f=>f.zones).reduce((s,z)=>{const a=getAreaM2(z);return s+(a||0);},0);
    const nZ=floors.flatMap(f=>f.zones).length;
    document.getElementById('model3dInfo').innerHTML=
      `${(n=>n+' etasje'+(n>1?'r':''))(floors.filter(f=>!erDelplan(f)).length)}${floors.some(erDelplan)?' ('+floors.length+' teikningar)':''}&nbsp;·&nbsp;${nZ} sone${nZ>1?'r':''}&nbsp;·&nbsp;<strong>${totalA.toFixed(0)} m² BRA</strong>`;

    // Skuggeutsnittet tett rundt bygget: ±100 m på eit 2048-kart gav
    // ~10 cm per piksel og grøtete skuggar på alle vanlege bygg
    (()=>{
      const bb=new THREE.Box3();
      scene3.traverse(o=>{if(o.isMesh&&o.userData.w)bb.expandByObject(o);});
      if(bb.isEmpty())return;
      const c=bb.getCenter(new THREE.Vector3());
      const r=Math.max(10,c.length()+bb.getSize(new THREE.Vector3()).length()/2+4);
      const sc=sun.shadow.camera;
      sc.left=-r;sc.right=r;sc.top=r;sc.bottom=-r;sc.far=Math.max(500,r*2+200);
      sc.updateProjectionMatrix();
    })();

    recenter();
    _applySun();
  }

  // ── Solsimulering ───────────────────────────────────────────
  // Standard solposisjonsformlar: deklinasjon + timevinkel → høgd/asimut
  function _solarPos(latDeg,dayOfYear,hour){
    const rad=Math.PI/180;
    const decl=23.44*Math.sin(2*Math.PI*(284+dayOfYear)/365);
    const H=(hour-12)*15;
    const lat=latDeg*rad,d=decl*rad,h=H*rad;
    const sinAlt=Math.sin(lat)*Math.sin(d)+Math.cos(lat)*Math.cos(d)*Math.cos(h);
    const alt=Math.asin(Math.max(-1,Math.min(1,sinAlt)));
    const cosAz=(Math.sin(d)-sinAlt*Math.sin(lat))/((Math.cos(alt)*Math.cos(lat))||1e-9);
    let az=Math.acos(Math.max(-1,Math.min(1,cosAz)))/rad;
    if(H>0)az=360-az;
    return{altDeg:alt/rad,azDeg:az};
  }
  const _bg3=()=>document.documentElement.getAttribute("data-theme")==="dark"?0x0f1113:0xebeff3;
  // Temabyte frå EntroPi medan 3D-modellen er open: tåka (og natta) må følgje.
  document.addEventListener('sxi-tema',()=>{if(scene3&&renderer3)_applySun();});
  const _MND=['jan','feb','mar','apr','mai','jun','jul','aug','sep','okt','nov','des'];
  const _DOY=[15,46,74,105,135,166,196,227,258,288,319,349];

  function _applySun(){
    if(!scene3||!renderer3)return;
    const u=scene3.userData;
    if(!u.sun)return;
    if(u.sunDisc){scene3.remove(u.sunDisc);u.sunDisc=null;}
    if(!_sunOn){
      // Tilbake til standardlys
      u.sun.position.copy(u.sunPos||new THREE.Vector3(50,90,40));u.sun.intensity=LYS3D.sun;u.sun.color.setHex(0xfff8f0);
      u.amb.intensity=LYS3D.amb;u.hemi.intensity=LYS3D.hemi;u.fill.intensity=LYS3D.fill;
      renderer3.setClearColor(_bg3(),0);if(scene3.fog)scene3.fog.color.setHex(_bg3());
      return;
    }
    const kl=document.getElementById('sxi_klima')?.value;
    const lat=parseFloat((typeof KLIMA!=='undefined'&&KLIMA[kl])?.lat)||60.4;
    const sp=_solarPos(lat,_DOY[_sunMonth-1],_sunHour);
    const nd=parseFloat(northI.value)||0;
    const ro=document.getElementById('sunReadout');
    const note=document.getElementById('sunPlaceNote');
    if(note)note.textContent='Klimastad: '+(kl||'Bergen')+' ('+lat.toFixed(1)+'°N) · nord '+Math.round(nd)+'° · vel klimastad i eksportdialogen';
    if(sp.altDeg<=0){
      // Natt — dus, blå scene
      u.sun.intensity=0.05;
      u.amb.intensity=0.55;u.hemi.intensity=0.2;u.fill.intensity=0.15;
      renderer3.setClearColor(0x1c2740,1);if(scene3.fog)scene3.fog.color.setHex(0x1c2740);
      if(ro)ro.textContent='Under horisonten';
      return;
    }
    // Kompass-asimut → bilde-/sceneretning (same konvensjon som calcSegments, invers)
    const imgAng=(sp.azDeg+nd-90)*Math.PI/180;
    const altRad=sp.altDeg*Math.PI/180,R=140;
    u.sun.position.set(R*Math.cos(altRad)*Math.cos(imgAng),R*Math.sin(altRad),R*Math.cos(altRad)*Math.sin(imgAng));
    u.sun.intensity=2.6*Math.min(1,Math.max(0.25,Math.sin(altRad)*1.6+0.2));
    u.sun.color.setHex(sp.altDeg<8?0xffb066:sp.altDeg<20?0xffd9a0:0xfff8f0);
    // Standardlyset har amb 1.4 + hemi 0.6 + fill 0.7 = meir diffust lys enn
    // sola gir. Då endrar biletet seg knapt naar ein drar i slideren, og
    // skuggane druknar. I solmodus må retningslyset dominere.
    u.amb.intensity=0.30+0.20*Math.min(1,Math.sin(altRad)*2);
    u.hemi.intensity=0.18;u.fill.intensity=0.10;
    renderer3.setClearColor(_bg3(),0);if(scene3.fog)scene3.fog.color.setHex(_bg3());
    // Soldisk for orientering
    const disc=new THREE.Mesh(new THREE.SphereGeometry(3,16,16),new THREE.MeshBasicMaterial({color:0xffdd66}));
    disc.position.copy(u.sun.position);
    scene3.add(disc);u.sunDisc=disc;
    if(ro)ro.textContent='Asimut '+Math.round(sp.azDeg)+'° · høgd '+Math.round(sp.altDeg)+'°';
  }

  function _syncSunUI(){
    const p=document.getElementById('sunPanel');
    const b=document.getElementById('model3dSunBtn');
    if(p)p.style.display=_sunOn?'block':'none';
    if(b)b.style.background=_sunOn?'rgba(255,255,255,.2)':'var(--surface)';
    const ml=document.getElementById('sunMonthLbl'),hl=document.getElementById('sunHourLbl');
    if(ml)ml.textContent=_MND[_sunMonth-1];
    if(hl)hl.textContent=(Math.floor(_sunHour))+':'+(_sunHour%1?'30':'00');
  }
  document.getElementById('model3dSunBtn').onclick=()=>{_sunOn=!_sunOn;_syncSunUI();_applySun();};
  document.getElementById('sunMonth').oninput=function(){_sunMonth=parseInt(this.value);_syncSunUI();_applySun();};
  document.getElementById('sunHour').oninput=function(){_sunHour=parseFloat(this.value);_syncSunUI();_applySun();};

  // ── PNG-eksport ─────────────────────────────────────────────
  // Lerretet er gjennomsiktig, så bakgrunnen frå #model3dScene (flate,
  // punktrutenett og logo) vert teikna inn bak modellen — same mål som CSS-en.
  const _logo3D=(()=>{
    const m=getComputedStyle(document.documentElement).getPropertyValue('--entro-ikon').match(/url\(["']?(.*?)["']?\)/);
    if(!m)return null;const im=new Image();im.src=m[1];return im;
  })();
  document.getElementById('model3dShotBtn').onclick=()=>{
    if(!renderer3||!scene3||!camera3)return;
    renderer3.render(scene3,camera3); // fersk render — buffer må vere fylt i same tick
    const gl=renderer3.domElement,W=gl.width,H=gl.height;
    const k=W/(CV.clientWidth||W);   // pikselforhold — prikkane i CSS-pikslar
    const ut=document.createElement('canvas');ut.width=W;ut.height=H;
    const c=ut.getContext('2d');
    const prikkar=(farge,r)=>{
      const t=document.createElement('canvas');t.width=t.height=Math.round(18*k);
      const tc=t.getContext('2d');tc.fillStyle=farge;tc.beginPath();tc.arc(0,0,r*k,0,2*Math.PI);tc.fill();
      return c.createPattern(t,'repeat');
    };
    c.fillStyle='#ebeff3';c.fillRect(0,0,W,H);
    c.fillStyle=prikkar('rgba(16,24,40,.09)',1.15);c.fillRect(0,0,W,H);
    if(_logo3D&&_logo3D.complete&&_logo3D.naturalWidth){
      // mask: right 6% bottom -6% / auto 82%
      const lh=H*0.82,lw=lh*_logo3D.naturalWidth/_logo3D.naturalHeight;
      const lx=(W-lw)*0.94,ly=(H-lh)*1.06;
      const l=document.createElement('canvas');l.width=W;l.height=H;
      const lc=l.getContext('2d');
      lc.fillStyle=(()=>{const t=document.createElement('canvas');t.width=t.height=Math.round(18*k);
        const tc=t.getContext('2d');tc.fillStyle='rgba(50,89,94,.24)';tc.beginPath();tc.arc(0,0,1.4*k,0,2*Math.PI);tc.fill();
        return lc.createPattern(t,'repeat');})();
      lc.fillRect(0,0,W,H);
      lc.globalCompositeOperation='destination-in';lc.drawImage(_logo3D,lx,ly,lw,lh);
      c.drawImage(l,0,0);
    }
    c.drawImage(gl,0,0);
    const a=document.createElement('a');
    a.download='SXI_3D_'+new Date().toISOString().slice(0,10)+'.png';
    a.href=ut.toDataURL('image/png');
    document.body.appendChild(a);a.click();document.body.removeChild(a);
  };

  // ── Klikkbar 3D — raycast → infoboks ───────────────────────
  const _ray=new THREE.Raycaster();
  function _clearPick(){
    if(_picked){_picked.material.emissive?.setHex(0x000000);_picked=null;}
    const box=document.getElementById('pick3dInfo');
    if(box)box.style.display='none';
  }
  function _pick3D(e){
    if(!scene3||!camera3)return;
    const r=CV.getBoundingClientRect();
    const ndc={x:((e.clientX-r.left)/r.width)*2-1,y:-((e.clientY-r.top)/r.height)*2+1};
    _ray.setFromCamera(ndc,camera3);
    const hits=_ray.intersectObjects(scene3.children,true).filter(h=>h.object.isMesh&&h.object.userData.pick);
    _clearPick();
    if(!hits.length)return;
    const obj=hits[0].object;
    _picked=obj;
    obj.material.emissive?.setHex(0x2a5550);
    const p=obj.userData.pick;
    const box=document.getElementById('pick3dInfo');
    box.innerHTML='<div style="font-weight:700;color:var(--dm-t1,#1f2937);margin-bottom:4px">'+p.title+'</div>'
      +p.rows.map(([k,v])=>'<div style="display:flex;justify-content:space-between;gap:14px"><span style="color:var(--dm-t3,#9ca3af)">'+k+'</span><span style="font-weight:600">'+v+'</span></div>').join('');
    const ovR=OV.getBoundingClientRect();
    box.style.display='block';
    let bx=e.clientX-ovR.left+14,by=e.clientY-ovR.top+14;
    box.style.left=bx+'px';box.style.top=by+'px';
    const br=box.getBoundingClientRect();
    if(br.right>ovR.right-8)box.style.left=(bx-br.width-28)+'px';
    if(br.bottom>ovR.bottom-8)box.style.top=(by-br.height-28)+'px';
  }

  function recenter(){
    if(!scene3)return;
    // Berre bygningsmeshar (userData.w) — elles blæs skuggefangar/soldisk/grid
    // opp bounding-boksen og kameraet hamnar altfor langt ute
    const box=new THREE.Box3();let _has=false;
    scene3.traverse(o=>{if(o.isMesh&&o.userData.w){box.expandByObject(o);_has=true;}});
    if(!_has)box.setFromObject(scene3);
    if(box.isEmpty()){tgt={x:0,y:0,z:0};sph.radius=40;}
    else{
      const c=box.getCenter(new THREE.Vector3());
      const s=box.getSize(new THREE.Vector3());
      const diagonal=Math.sqrt(s.x*s.x+s.y*s.y+s.z*s.z);
      tgt={x:c.x,y:Math.max(0,c.y*0.2),z:c.z};
      // Avstanden der heile bygget (kula rundt boksen) får plass i det
      // smalaste synsfeltet. diagonal*0.5 sette kameraet på kula, altså
      // ofte inne i bygget.
      const vHalf=(camera3?.fov||42)*Math.PI/360;
      const hHalf=Math.atan(Math.tan(vHalf)*(camera3?.aspect||1.5));
      sph.radius=Math.max(8,(diagonal/2)/Math.sin(Math.min(vHalf,hHalf))*0.9);
      sph.phi=0.95;sph.theta=0.6;
    }
    updateCam();
  }

  function updateCam(){
    if(!camera3)return;
    camera3.position.set(
      tgt.x+sph.radius*Math.sin(sph.phi)*Math.sin(sph.theta),
      tgt.y+sph.radius*Math.cos(sph.phi),
      tgt.z+sph.radius*Math.sin(sph.phi)*Math.cos(sph.theta)
    );
    camera3.lookAt(tgt.x,tgt.y,tgt.z);
  }

  // Orbit controls
  CV.addEventListener('mousedown',e=>{
    if(e.shiftKey)pan=true;else orb=true;
    lastM={x:e.clientX,y:e.clientY};
    _downPos={x:e.clientX,y:e.clientY};
    e.preventDefault();
  });
  // Klikk (utan drag) → vis info om vegg/takflate
  CV.addEventListener('mouseup',e=>{
    if(_downPos&&Math.hypot(e.clientX-_downPos.x,e.clientY-_downPos.y)<5)_pick3D(e);
    _downPos=null;
  });

  
  CV.addEventListener('touchstart',e=>{orb=true;lastM={x:e.touches[0].clientX,y:e.touches[0].clientY};e.preventDefault();},{passive:false});
  document.addEventListener('mousemove',e=>{
    if(!orb&&!pan)return;
    const dx=e.clientX-lastM.x,dy=e.clientY-lastM.y;
    lastM={x:e.clientX,y:e.clientY};
    if(pan){
      const sp=sph.radius*0.001;
      const ca=Math.cos(sph.theta),sa=Math.sin(sph.theta);
      tgt.x-=(ca*dx-sa*dy*0)*sp; // simplified pan
      tgt.z-=(sa*dx+ca*dy*0)*sp;
      tgt.y+=dy*sp*1.5;
    } else {
      sph.theta-=dx*0.007;
      sph.phi=Math.max(0.05,Math.min(Math.PI*0.47,sph.phi+dy*0.007));
    }
    updateCam();
  });
  document.addEventListener('touchmove',e=>{
    if(!orb)return;
    const dx=e.touches[0].clientX-lastM.x,dy=e.touches[0].clientY-lastM.y;
    lastM={x:e.touches[0].clientX,y:e.touches[0].clientY};
    sph.theta-=dx*0.01;sph.phi=Math.max(0.05,Math.min(Math.PI*0.47,sph.phi+dy*0.01));
    updateCam();
  },{passive:false});
  document.addEventListener('mouseup',()=>{orb=false;pan=false;});
  document.addEventListener('touchend',()=>{orb=false;});
  CV.addEventListener('wheel',e=>{
    sph.radius=Math.max(3,Math.min(300,sph.radius*Math.pow(1.001,e.deltaY)));
    updateCam();e.preventDefault();
  },{passive:false});

  // Lappar som ligg oppå kvarandre på skjermen: den med høgast prioritet
  // (sonekort > høgdemål > vegglengd, større før mindre) står, dei andre vert
  // gøymde til det er plass — zoom inn, så kjem dei fram. Same info finst
  // òg ved klikk på veggen/sona.
  const _rv=new THREE.Vector3(),_rr=new THREE.Vector3(),_ru=new THREE.Vector3(),_re=new THREE.Vector3();
  let _ryddN=0;
  function _ryddLappar(){
    const W=CV.clientWidth,H=CV.clientHeight;if(!W||!H)return;
    const l=[];scene3.traverse(o=>{if(o.isSprite&&o.userData.prio!=null)l.push(o);});
    l.sort((a,b)=>b.userData.prio-a.userData.prio);
    _rr.setFromMatrixColumn(camera3.matrixWorld,0);_ru.setFromMatrixColumn(camera3.matrixWorld,1);
    const boksar=[];
    l.forEach(s=>{
      s.getWorldPosition(_rv);
      _re.copy(_rv).addScaledVector(_rr,s.scale.x/2).addScaledVector(_ru,s.scale.y/2).project(camera3);
      _rv.project(camera3);
      if(_rv.z>1){s.visible=false;return;}
      const hw=Math.abs(_re.x-_rv.x)*W/2+3,hh=Math.abs(_re.y-_rv.y)*H/2+2;
      const x=(_rv.x+1)*W/2,y=(1-_rv.y)*H/2;
      const b={x0:x-hw,x1:x+hw,y0:y-hh,y1:y+hh};
      const kryss=boksar.some(q=>q.x0<b.x1&&b.x0<q.x1&&q.y0<b.y1&&b.y0<q.y1);
      s.visible=!kryss;
      if(!kryss)boksar.push(b);
    });
  }
  function start(){
    stop();
    (function loop(){animId3=requestAnimationFrame(loop);
      if((_ryddN++%6)===0)_ryddLappar();
      const w=CV.clientWidth,h=CV.clientHeight;
      if(renderer3.domElement.width!==w||renderer3.domElement.height!==h){
        renderer3.setSize(w,h,false);camera3.aspect=w/h;camera3.updateProjectionMatrix();
      }
      if(_growT0){
        const t=(performance.now()-_growT0)/900;
        if(t>=1){scene3.scale.y=1;_growT0=0;}
        else scene3.scale.y=Math.max(0.001,1-Math.pow(1-t,3)); // ease-out cubic
      }
      renderer3.render(scene3,camera3);
    })();
  }
  function stop(){if(animId3){cancelAnimationFrame(animId3);animId3=null;}}
  // Eksponerer rebuild-funksjon (bevarar kameraposisjon) for bruk frå ghost-offset-handterarar
  window._rebuild3D=function(){
    if(!scene3)return;
    const _s={theta:sph.theta,phi:sph.phi,radius:sph.radius};
    const _t={x:tgt.x,y:tgt.y,z:tgt.z};
    try{build();_skannStil();}catch(e){console.error('3D rebuild error:',e);}
    sph.theta=_s.theta;sph.phi=_s.phi;sph.radius=_s.radius;
    tgt.x=_t.x;tgt.y=_t.y;tgt.z=_t.z;
    updateCam();
  };
})();

// Debounca 3D-rebuild — vert kalla frå updateResults() slik at 3D-modellen
// oppdaterast live når brukaren gjer endringar, utan for mange dyre rebuilds.
let _rebuild3DTimer=null;
function _rebuild3DDebounced(){
  if(document.getElementById('model3dOverlay')?.style.display!=='flex')return;
  clearTimeout(_rebuild3DTimer);
  _rebuild3DTimer=setTimeout(()=>{window._rebuild3D&&window._rebuild3D();},180);
}

// ── Vindauge-ekspansjon for fasade + 3D ───────────────────────
// Tar eit vindaugsobjekt med antal>1 og segmentlengde i meter, returnerer
// array med éin oppføring per stk, kvar med sine eigne t0/t1. Plasseringa kjem
// frå `w.posT` når brukaren har flytta stykka sjølv, elles frå ei jamn
// fordeling rundt gruppesenteret (sjå winCentres).
// Vegg med opningar til 3D: elevasjonen (u langs veggen, v opp) som form med
// hòl, ekstrudert tjukna T. Dører (opning frå golvet) vert hakk i nedkanten,
// sidan eit hòl må liggje heilt inne i forma. Overlappande opningar vert
// slegne saman — kryssande hòl gir øydelagd triangulering.
function _veggGeo(L,H,T,eS,eE,hol){
  const top=H-0.03;
  const r=hol.map(o=>({u0:Math.max(0.02,o.u0),u1:Math.min(L-0.02,o.u1),v0:Math.max(0,o.v0),v1:Math.min(top,o.v1)}))
    .filter(o=>o.u1-o.u0>0.03&&o.v1-o.v0>0.03);
  for(let endra=true;endra;){
    endra=false;
    for(let i=0;i<r.length&&!endra;i++)for(let j=i+1;j<r.length;j++){
      const a=r[i],b=r[j];
      if(a.u0<b.u1+0.02&&b.u0<a.u1+0.02&&a.v0<b.v1+0.02&&b.v0<a.v1+0.02){
        r[i]={u0:Math.min(a.u0,b.u0),u1:Math.max(a.u1,b.u1),v0:Math.min(a.v0,b.v0),v1:Math.max(a.v1,b.v1)};
        r.splice(j,1);endra=true;break;
      }
    }
  }
  const sh=new THREE.Shape();
  sh.moveTo(-eS,0);
  r.filter(o=>o.v0<0.02).sort((a,b)=>a.u0-b.u0)
    .forEach(o=>{sh.lineTo(o.u0,0);sh.lineTo(o.u0,o.v1);sh.lineTo(o.u1,o.v1);sh.lineTo(o.u1,0);});
  sh.lineTo(L+eE,0);sh.lineTo(L+eE,H);sh.lineTo(-eS,H);
  r.filter(o=>o.v0>=0.02).forEach(o=>{
    const p=new THREE.Path();
    p.moveTo(o.u0,o.v0);p.lineTo(o.u0,o.v1);p.lineTo(o.u1,o.v1);p.lineTo(o.u1,o.v0);
    sh.holes.push(p);
  });
  // Innvendig vegg utan tjukn: ei flat flate med dei same opningane
  if(!(T>0))return new THREE.ShapeGeometry(sh,1);
  return new THREE.ExtrudeGeometry(sh,{depth:T,bevelEnabled:false,curveSegments:1});
}
function expandWindows(w, segLenM){
  // Bruk alltid breddeMm for faktisk breidde — t0/t1 er berre senterposisjon
  const winWidthM=w.breddeMm/1000;
  return winCentres(w,winWidthM,segLenM).map(c=>{
    const {t0,t1}=fitSpanT(c,winWidthM,segLenM);
    return{...w,antal:1,posT:null,t0,t1};
  });
}

function renderFasadeView(){
  const wrap=document.getElementById('fasadeWrap');
  const allZones=floors.flatMap((f,fi)=>f.zones.map(z=>({z,fi,f})));
  const yvZones=allZones.filter(({z})=>{
    const segs=calcSegments(z.pts,getHoyde(z));
    return segs&&segs.some(s=>!(z.skillevegg||new Set()).has(s.idx));
  });

  if(!yvZones.length){
    wrap.innerHTML='<div class="empty"><div class="empty-icon">▭</div>Teikn soner med ytterveggar<br>for å sjå fasadevisualiseringa</div>';
    return;
  }
  if(!mmPerImgPx&&!yvZones.some(({z})=>z.areaOverride!=null)){
    wrap.innerHTML='<div class="empty"><div class="empty-icon">⊕</div>Kalibrer teikninga først<br>for å få korrekte mål på fasadane</div>';
    return;
  }

  // Compass direction order for grouping: N, NØ, Ø, SØ, S, SV, V, NV
  const DIR_ORDER=['Nord','Nordøst','Øst','Sørøst','Sør','Sørvest','Vest','Nordvest'];
  const DIR_SHORT={'Nord':'N','Nordøst':'NØ','Øst':'Ø','Sørøst':'SØ','Sør':'S','Sørvest':'SV','Vest':'V','Nordvest':'NV'};
  const DIR_DEG={'Nord':0,'Nordøst':45,'Øst':90,'Sørøst':135,'Sør':180,'Sørvest':225,'Vest':270,'Nordvest':315};

  // Collect all YV segments across all zones, grouped by direction
  const byDir={};
  yvZones.forEach(({z,fi,f})=>{
    const segs=calcSegments(z.pts,getHoyde(z),mppForFloor(f))||[];
    const sk=z.skillevegg||new Set();
    const labels=getFacadeLabels(z,segs);
    segs.forEach((seg,si)=>{
      if(sk.has(seg.idx))return;
      const dir=seg.dir;
      if(!byDir[dir])byDir[dir]=[];
      byDir[dir].push({seg,z,fi,f,label:labels[si]});
    });
  });

  const dirs=DIR_ORDER.filter(d=>byDir[d]);
  if(!dirs.length){
    wrap.innerHTML='<div class="empty"><div class="empty-icon">▭</div>Ingen ytterveggar funne</div>';
    return;
  }

  // Build HTML
  let html=`
  <div style="padding:10px 0 4px;display:flex;align-items:center;justify-content:space-between">
    <div style="font-size:11px;font-weight:700;color:var(--text3);text-transform:uppercase;letter-spacing:.08em">Utvikla fasadar</div>
    <button onclick="printFasadeView()" style="padding:3px 10px;font-size:11px;border:1px solid var(--border2);border-radius:5px;background:var(--surface);color:var(--text2);cursor:pointer;font-family:inherit;display:flex;align-items:center;gap:4px">🖨 Skriv ut</button>
  </div>`;

  dirs.forEach(dir=>{
    const entries=byDir[dir];
    const shortDir=DIR_SHORT[dir];
    const azDeg=DIR_DEG[dir];

    // Total facade width and max height for this direction
    const totalLenM=entries.reduce((s,e)=>s+(e.seg.lenM||0),0);
    const maxH=Math.max(...entries.map(e=>getHoyde(e.z)));
    const totalWinA=entries.reduce((s,e)=>{
      const wins=(e.z.windows||[]).filter(w=>w.segIdx===e.seg.idx);
      return s+wins.reduce((ws,w)=>(w.breddeMm/1000)*(w.hoyMm/1000)*w.antal+ws,0);
    },0);
    const totalBrutto=entries.reduce((s,e)=>s+(e.seg.areaM2||0),0);
    const totalNetto=totalBrutto-totalWinA;
    // Gavlflater for denne retningen
    const totalGavlA=entries.reduce((s,e)=>{
      const gavl=(e.z.gavlflater||[]).find(g=>g.segIdx===e.seg.idx);
      return s+(gavl?gavl.area:0);
    },0);
    const maxGavlH=Math.max(0,...entries.map(e=>{
      const gavl=(e.z.gavlflater||[]).find(g=>g.segIdx===e.seg.idx);
      return gavl?Math.max(...gavl.profile.map(p=>p.h)):0;
    }));

    // Canvas dimensions — scale to fit sidebar (~280px wide typical)
    const CANVAS_W=268;
    const scale=totalLenM>0?Math.min((CANVAS_W-24)/totalLenM,60):30; // px per m, max 60
    const canvasH=Math.round((maxH+maxGavlH)*scale)+40; // +40 for base/labels
    const drawH=Math.round(maxH*scale);
    const drawGavlH=Math.round(maxGavlH*scale);

    html+=`
    <div style="background:var(--surface);border:1px solid var(--border);border-radius:var(--r-lg);margin-bottom:10px;overflow:hidden;box-shadow:var(--shadow-sm)">
      <!-- Header -->
      <div style="display:flex;align-items:center;justify-content:space-between;padding:8px 12px;background:var(--surface2);border-bottom:1px solid var(--border)">
        <div style="display:flex;align-items:center;gap:8px">
          <div style="width:28px;height:28px;border-radius:50%;background:var(--accent);display:flex;align-items:center;justify-content:center;position:relative;flex-shrink:0">
            ${compassSvgSmall(azDeg)}
          </div>
          <div>
            <div style="font-size:13px;font-weight:700;color:var(--text)">${dir}</div>
            <div style="font-size:10px;color:var(--text3)">${entries.length} vegg${entries.length>1?'ar':''} · ${totalLenM.toFixed(1)} m brei</div>
          </div>
        </div>
        <div style="text-align:right">
          <div style="font-size:11px;font-weight:600;color:var(--text)">${totalBrutto.toFixed(1)} m²</div>
          <div style="font-size:10px;color:var(--text3)">brutto</div>
        </div>
      </div>
      <!-- Canvas drawing -->
      <div style="padding:10px 12px 6px">
        <canvas id="fac_${dir.replace(/[^a-z]/gi,'_')}" width="${CANVAS_W}" height="${canvasH}" style="width:${CANVAS_W}px;height:${canvasH}px;display:block"></canvas>
      </div>
      <!-- Area stats row -->
      <div style="display:flex;border-top:1px solid var(--border)">
        <div style="flex:1;padding:7px 10px;text-align:center;border-right:1px solid var(--border)">
          <div style="font-size:12px;font-weight:700;color:var(--text)">${totalBrutto.toFixed(1)}</div>
          <div style="font-size:10px;color:var(--text3)">Vegg m²</div>
        </div>
        ${totalGavlA>0?`<div style="flex:1;padding:7px 10px;text-align:center;border-right:1px solid var(--border)">
          <div style="font-size:12px;font-weight:700;color:#d97706">${totalGavlA.toFixed(1)}</div>
          <div style="font-size:10px;color:var(--text3)">Gavl m²</div>
        </div>`:''}
        <div style="flex:1;padding:7px 10px;text-align:center;border-right:1px solid var(--border)">
          <div style="font-size:12px;font-weight:700;color:#0891b2">${totalWinA.toFixed(1)}</div>
          <div style="font-size:10px;color:var(--text3)">Glas m²</div>
        </div>
        <div style="flex:1;padding:7px 10px;text-align:center">
          <div style="font-size:12px;font-weight:700;color:var(--accent)">${(totalNetto+totalGavlA).toFixed(1)}</div>
          <div style="font-size:10px;color:var(--text3)">Netto m²</div>
        </div>
      </div>
    </div>`;
  });

  // Summary table
  const grandBrutto=dirs.reduce((s,d)=>s+byDir[d].reduce((ss,e)=>ss+(e.seg.areaM2||0),0),0);
  const grandGavl=dirs.reduce((s,d)=>s+byDir[d].reduce((ss,e)=>{
    const gavl=(e.z.gavlflater||[]).find(g=>g.segIdx===e.seg.idx);
    return ss+(gavl?gavl.area:0);
  },0),0);
  const grandWin=dirs.reduce((s,d)=>s+byDir[d].reduce((ss,e)=>{
    const wins=(e.z.windows||[]).filter(w=>w.segIdx===e.seg.idx);
    return ss+wins.reduce((ws,w)=>(w.breddeMm/1000)*(w.hoyMm/1000)*w.antal+ws,0);
  },0),0);
  const grandNetto=grandBrutto+grandGavl-grandWin;
  const glasPct=(grandBrutto+grandGavl)>0?(grandWin/(grandBrutto+grandGavl)*100):0;

  html+=`
  <div style="background:var(--surface);border:1px solid var(--border);border-radius:var(--r-lg);padding:10px 12px;margin-bottom:12px;box-shadow:var(--shadow-sm)">
    <div style="font-size:10px;font-weight:700;color:var(--text3);text-transform:uppercase;letter-spacing:.08em;margin-bottom:8px">Samandrag fasadar</div>
    <table style="width:100%;border-collapse:collapse;font-size:12px">
      <thead><tr>
        <th style="text-align:left;padding:4px 6px;color:var(--text3);font-weight:600;border-bottom:1px solid var(--border)">Retning</th>
        <th style="text-align:right;padding:4px 6px;color:var(--text3);font-weight:600;border-bottom:1px solid var(--border)">Vegg</th>
        <th style="text-align:right;padding:4px 6px;color:var(--text3);font-weight:600;border-bottom:1px solid var(--border)">Gavl</th>
        <th style="text-align:right;padding:4px 6px;color:var(--text3);font-weight:600;border-bottom:1px solid var(--border)">Glas</th>
        <th style="text-align:right;padding:4px 6px;color:var(--text3);font-weight:600;border-bottom:1px solid var(--border)">Netto</th>
      </tr></thead>
      <tbody>`;

  dirs.forEach(dir=>{
    const entries=byDir[dir];
    const brutto=entries.reduce((s,e)=>s+(e.seg.areaM2||0),0);
    const gavlA=entries.reduce((s,e)=>{
      const gavl=(e.z.gavlflater||[]).find(g=>g.segIdx===e.seg.idx);
      return s+(gavl?gavl.area:0);
    },0);
    const winA=entries.reduce((s,e)=>{
      const wins=(e.z.windows||[]).filter(w=>w.segIdx===e.seg.idx);
      return s+wins.reduce((ws,w)=>(w.breddeMm/1000)*(w.hoyMm/1000)*w.antal+ws,0);
    },0);
    const netto=brutto+gavlA-winA;
    html+=`<tr style="border-bottom:1px solid var(--border)">
      <td style="padding:5px 6px;font-weight:600;color:var(--accent)">${DIR_SHORT[dir]}</td>
      <td style="padding:5px 6px;text-align:right;font-family:inherit;color:var(--text2)">${brutto.toFixed(1)}</td>
      <td style="padding:5px 6px;text-align:right;font-family:inherit;color:#d97706">${gavlA>0?gavlA.toFixed(1):'—'}</td>
      <td style="padding:5px 6px;text-align:right;font-family:inherit;color:#0891b2">${winA.toFixed(1)}</td>
      <td style="padding:5px 6px;text-align:right;font-family:inherit;color:var(--accent)">${netto.toFixed(1)}</td>
    </tr>`;
  });

  html+=`<tr style="background:var(--surface2)">
    <td style="padding:6px;font-weight:700;color:var(--text)">Totalt</td>
    <td style="padding:6px;text-align:right;font-weight:700;font-family:inherit">${grandBrutto.toFixed(1)}</td>
    <td style="padding:6px;text-align:right;font-weight:700;font-family:inherit;color:#d97706">${grandGavl>0?grandGavl.toFixed(1):'—'}</td>
    <td style="padding:6px;text-align:right;font-weight:700;font-family:inherit;color:#0891b2">${grandWin.toFixed(1)}</td>
    <td style="padding:6px;text-align:right;font-weight:700;font-family:inherit;color:var(--accent)">${grandNetto.toFixed(1)}</td>
  </tr></tbody></table>
  <div style="margin-top:8px;display:flex;align-items:center;gap:6px">
    <div style="flex:1;height:6px;border-radius:3px;background:var(--surface3);overflow:hidden">
      <div style="height:100%;width:${Math.min(glasPct,100).toFixed(1)}%;background:#0891b2;border-radius:3px;transition:width .4s"></div>
    </div>
    <div style="font-size:11px;font-weight:600;color:#0891b2;white-space:nowrap">${glasPct.toFixed(1)}% glas</div>
  </div>
  </div>`;

  wrap.innerHTML=html;

  // Draw each facade canvas
  dirs.forEach(dir=>{
    const entries=byDir[dir];
    const canvasId='fac_'+dir.replace(/[^a-z]/gi,'_');
    const c=document.getElementById(canvasId);
    if(!c)return;
    const cx=c.getContext('2d');
    const W=c.width,H=c.height;
    const CANVAS_W=W;

    const totalLenM=entries.reduce((s,e)=>s+(e.seg.lenM||0),0);
    const maxH=Math.max(...entries.map(e=>getHoyde(e.z)));
    const scale=totalLenM>0?Math.min((CANVAS_W-24)/totalLenM,60):30;
    const drawH=Math.round(maxH*scale);
    const maxGavlH_c=Math.max(0,...entries.map(e=>{
      const gavl=(e.z.gavlflater||[]).find(g=>g.segIdx===e.seg.idx);
      return gavl?Math.max(...gavl.profile.map(p=>p.h)):0;
    }));
    const drawGavlH_c=Math.round(maxGavlH_c*scale);
    const marginL=12,marginTop=6,groundY=marginTop+drawGavlH_c+drawH;

    cx.clearRect(0,0,W,H);

    // Sky gradient (taller om det er gavlar)
    const skyGrad=cx.createLinearGradient(0,marginTop,0,groundY);
    skyGrad.addColorStop(0,'#dbeafe');skyGrad.addColorStop(1,'#f0f9ff');
    cx.fillStyle=skyGrad;
    cx.fillRect(marginL,marginTop,totalLenM*scale,drawGavlH_c+drawH);

    let curX=marginL;
    entries.forEach((e,ei)=>{
      const segW=Math.round((e.seg.lenM||0)*scale);
      const segH=Math.round(getHoyde(e.z)*scale);
      const segTop=groundY-segH;
      const color=COLORS[ei%COLORS.length];

      // Wall fill
      cx.fillStyle=color+'18';
      cx.fillRect(curX,segTop,segW,segH);

      // Wall outline
      cx.strokeStyle=color+'99';cx.lineWidth=1.5;
      cx.strokeRect(curX+0.5,segTop+0.5,segW-1,segH-1);

      // Gavlflate (trekant over veggtopp)
      const _gavl=(e.z.gavlflater||[]).find(g=>g.segIdx===e.seg.idx);
      if(_gavl&&_gavl.profile&&_gavl.profile.length>=2){
        cx.beginPath();
        // Øvre profil
        cx.moveTo(curX+_gavl.profile[0].t*segW, segTop-_gavl.profile[0].h*scale);
        for(let _pi=1;_pi<_gavl.profile.length;_pi++){
          cx.lineTo(curX+_gavl.profile[_pi].t*segW, segTop-_gavl.profile[_pi].h*scale);
        }
        // Nedre kant (veggtopp)
        cx.lineTo(curX+segW, segTop);
        cx.lineTo(curX, segTop);
        cx.closePath();
        cx.fillStyle=color+'22';cx.fill();
        cx.strokeStyle=color+'bb';cx.lineWidth=1.5;cx.stroke();
        // Gavl-areal-label
        if(segW>24&&_gavl.area>0){
          const _gLabel='⊿ '+_gavl.area.toFixed(1)+'m²';
          cx.font='7px Inter,sans-serif';
          cx.fillStyle=color;cx.textAlign='center';cx.textBaseline='middle';
          const _apexY=segTop-Math.max(..._gavl.profile.map(p=>p.h))*scale;
          const _midY=(_apexY+segTop)/2;
          cx.fillText(_gLabel,curX+segW/2,_midY);
        }
      }

      // Segment separator
      if(ei>0){
        cx.beginPath();cx.moveTo(curX,segTop);cx.lineTo(curX,groundY);
        cx.strokeStyle='rgba(0,0,0,.15)';cx.lineWidth=1;cx.setLineDash([3,3]);cx.stroke();cx.setLineDash([]);
      }

      // Zone label at top of segment
      cx.font='bold 8px Inter,sans-serif';
      cx.fillStyle=color;cx.textAlign='center';cx.textBaseline='top';
      const lbl=e.z.name+(floors.length>1?' ('+e.f.name+')':'');
      const lblW=cx.measureText(lbl).width+8;
      if(segW>lblW+4){
        cx.fillStyle='rgba(255,255,255,.85)';
        cx.beginPath();cx.roundRect(curX+(segW-lblW)/2,segTop+4,lblW,13,3);cx.fill();
        cx.fillStyle=color;cx.fillText(lbl,curX+segW/2,segTop+7);
      }

      // Width label (bottom, below ground line)
      if(e.seg.lenM!=null&&segW>28){
        cx.font='8px Inter,sans-serif';
        cx.fillStyle='#6b7280';cx.textAlign='center';cx.textBaseline='top';
        cx.fillText(e.seg.lenM.toFixed(1)+'m',curX+segW/2,groundY+3);
      }

      // Windows & doors on this segment
      const wins=(e.z.windows||[]).filter(w=>w.segIdx===e.seg.idx);
      wins.forEach(w=>{
        // Expand antal>1 into individually positioned windows
        const expanded=expandWindows(w, e.seg.lenM||1);
        expanded.forEach(ew=>{
        const wHeightM=ew.hoyMm/1000;
        const t0px=ew.t0*segW;
        const t1px=ew.t1*segW;
        const wLeft=curX+t0px;
        const wRight=curX+t1px;
        const actualPxW=wRight-wLeft;
        const isDoor=ew.type==='dor';

        if(actualPxW>=2){
          if(isDoor){
            // Door — goes to ground
            const doorTop=groundY-wHeightM*scale;
            cx.fillStyle='rgba(245,158,11,.15)';
            cx.fillRect(wLeft,doorTop,actualPxW,wHeightM*scale);
            cx.strokeStyle='#d97706';cx.lineWidth=1.5;
            cx.strokeRect(wLeft,doorTop,actualPxW,wHeightM*scale);
            if(actualPxW>8){
              cx.beginPath();
              cx.arc(wLeft,groundY,actualPxW*0.7,-(Math.PI/2),-(Math.PI/2)+(Math.PI/3));
              cx.strokeStyle='rgba(217,119,6,.4)';cx.lineWidth=1;cx.setLineDash([2,2]);cx.stroke();cx.setLineDash([]);
            }
          } else {
            // Window
            const wTopAdj=segTop+Math.max(6,segH-wHeightM*scale-Math.min(0.9*scale,segH*0.35));
            const glassGrad=cx.createLinearGradient(wLeft,wTopAdj,wRight,wTopAdj+wHeightM*scale);
            glassGrad.addColorStop(0,'rgba(186,230,253,.85)');
            glassGrad.addColorStop(0.4,'rgba(224,242,254,.95)');
            glassGrad.addColorStop(1,'rgba(125,211,252,.6)');
            cx.fillStyle=glassGrad;
            cx.fillRect(wLeft,wTopAdj,actualPxW,wHeightM*scale);
            cx.strokeStyle='#0891b2';cx.lineWidth=1.5;
            cx.strokeRect(wLeft,wTopAdj,actualPxW,wHeightM*scale);
            // Vertical midline divider
            if(actualPxW>10&&wHeightM*scale>10){
              cx.beginPath();
              cx.moveTo(wLeft+actualPxW/2,wTopAdj);cx.lineTo(wLeft+actualPxW/2,wTopAdj+wHeightM*scale);
              cx.moveTo(wLeft,wTopAdj+wHeightM*scale/2);cx.lineTo(wLeft+actualPxW,wTopAdj+wHeightM*scale/2);
              cx.strokeStyle='rgba(8,145,178,.4)';cx.lineWidth=0.75;cx.stroke();
            }
          }
        }
        }); // end expanded.forEach
      });

      // Height annotation on first segment
      if(ei===0&&segH>24){
        cx.font='7px Inter,sans-serif';
        cx.fillStyle='#94a3b8';cx.textAlign='left';cx.textBaseline='middle';
        const hLabel=getHoyde(e.z).toFixed(1)+'m';
        cx.save();cx.translate(curX+3,segTop+segH/2);cx.rotate(-Math.PI/2);cx.fillText(hLabel,0,0);cx.restore();
        // Tick marks
        cx.beginPath();cx.moveTo(curX+1,segTop);cx.lineTo(curX+5,segTop);
        cx.moveTo(curX+1,groundY);cx.lineTo(curX+5,groundY);
        cx.strokeStyle='#cbd5e1';cx.lineWidth=1;cx.stroke();
      }

      curX+=segW;
    });

    // Ground line
    cx.beginPath();cx.moveTo(marginL,groundY);cx.lineTo(marginL+totalLenM*scale,groundY);
    cx.strokeStyle='#64748b';cx.lineWidth=2;cx.stroke();
    // Ground hatch
    cx.save();cx.beginPath();
    for(let xi=0;xi<totalLenM*scale;xi+=6){
      cx.moveTo(marginL+xi,groundY);cx.lineTo(marginL+xi-6,groundY+6);
    }
    cx.strokeStyle='#94a3b8';cx.lineWidth=0.75;cx.stroke();cx.restore();
  });
}

function compassSvgSmall(azDeg){
  // Returns an SVG arrow pointing at azDeg (0=N=up) inside a 28px circle
  const rad=(azDeg-90)*Math.PI/180;
  const tx=14+Math.cos(rad)*8,ty=14+Math.sin(rad)*8;
  const bx=14-Math.cos(rad)*6,by=14-Math.sin(rad)*6;
  const px=-Math.sin(rad),py=Math.cos(rad);
  const pts=`${tx},${ty} ${bx+px*3},${by+py*3} ${bx-px*3},${by-py*3}`;
  return `<svg width="28" height="28" viewBox="0 0 28 28" style="position:absolute;inset:0">
    <polygon points="${pts}" fill="white" opacity="0.9"/>
    <text x="14" y="14" text-anchor="middle" dominant-baseline="central" font-size="7" font-weight="bold" fill="white" font-family="Inter,sans-serif">N</text>
  </svg>`;
}

function printFasadeView(){
  // Collect all canvases as images
  const wrap=document.getElementById('fasadeWrap');
  const canvases=wrap.querySelectorAll('canvas');
  let imgHtml='';
  canvases.forEach(c=>{
    imgHtml+=`<img src="${c.toDataURL('image/png')}" style="max-width:100%;display:block;margin-bottom:12px">`;
  });
  const w=window.open('','_blank','width=700,height=900');
  w.document.write(`<!DOCTYPE html><html><head>
    <title>Fasadar — SXI-generatoren</title>
    <style>
      body{font-family:'Inter',system-ui,sans-serif;padding:32px;color:#1a202c;max-width:660px;margin:0 auto}
      h1{font-size:18px;margin-bottom:4px;color:#1a7a6e}
      .sub{font-size:12px;color:#718096;margin-bottom:24px}
      img{border:1px solid #e2e6ed;border-radius:8px;margin-bottom:16px}
      table{width:100%;border-collapse:collapse;font-size:12px;margin-top:24px}
      th{text-align:left;padding:6px 8px;background:#f7fafc;border:1px solid #e2e6ed;font-weight:600}
      td{padding:6px 8px;border:1px solid #e2e6ed}
      @media print{body{padding:16px}}
    </style>
  </head><body>
    <h1>Utvikla fasadar</h1>
    <div class="sub">Generert av SXI-generatoren · Entro AS · ${new Date().toLocaleDateString('nb-NO')}</div>
    ${imgHtml}
  </body></html>`);
  w.document.close();
  setTimeout(()=>w.print(),400);
}

(function init(){
  const r=cwrap.getBoundingClientRect();
  cv.width=r.width;cv.height=r.height;
  drawCompass();
})();

